<?php
namespace App\Http\Controllers\Api;
use App\Models\{Banner,Category,Coupon,Product,Complaint,SiteSetting,ProductVariant};
use App\Services\AuthService;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Facades\DB;

class LegacyController extends BaseApiController
{
 public function products(Request $r){if($r->query('action')==='get'){ $id=(string)$r->query('id');$p=Product::with(['category','variants'])->where(fn($q)=>$q->where('id',$id)->orWhere('legacy_id',$id)->orWhere('slug',$id))->first();return $p?$this->ok($p):$this->fail('Product not found',404);}return $this->ok(Product::with('category')->where('is_active',true)->orderBy('sort_order')->latest()->get());}
 public function categories(){return $this->ok(Category::where('is_active',true)->orderBy('sort_order')->orderBy('name')->get());}
 public function banners(Request $r){$action=$r->query('action','list');if($action==='list')return $this->ok(Banner::where('is_active',true)->orderBy('banner_type')->orderBy('sort_order')->get());if(!$r->user()||$r->user()->role!=='admin')return $this->fail('Admin access required',403);if($action==='admin-list'){return $this->ok(Banner::orderBy('banner_type')->orderBy('sort_order')->get());}$d=$r->all();if($action==='delete'){Banner::whereKey($d['id']??'')->delete();return $this->ok();}if(in_array($action,['create','update'],true)){ $data=$r->validate(['banner_type'=>'nullable|in:hero,promo','title'=>'nullable|string|max:255','alt_text'=>'nullable|string|max:255','image_url'=>'required|string','link_url'=>'nullable|string','sort_order'=>'nullable|integer','is_active'=>'nullable|boolean']);$data['banner_type']=$data['banner_type']??'hero';$data['alt_text']=$data['alt_text']??'ফল বাজার ব্যানার';$data['sort_order']=$data['sort_order']??0;$data['is_active']=$data['is_active']??true;$b=$action==='create'?Banner::create($data):tap(Banner::findOrFail($d['id']),fn($x)=>$x->update($data));return $this->ok($b,$action==='create'?201:200);}return $this->fail('Unknown banner action',404);}
 public function coupons(Request $r){$c=Coupon::whereRaw('UPPER(code)=?', [strtoupper((string)$r->query('code'))])->first();return $this->ok($c?[$c]:[]);}
 public function auth(Request $r, AuthService $service){$action=$r->query('action');$legacyUser=$r->user() ?: auth('sanctum')->user();if($action==='register'){ $d=$r->validate(['name'=>'required|string|min:2','phone'=>'required|string|min:11','email'=>'nullable|email','password'=>'required|string|min:6']);return $this->ok($service->register($d),201);}if($action==='login'){ $d=$r->validate(['identifier'=>'required|string','email'=>'nullable|string','password'=>'required|string']);return $this->ok($service->login($d['identifier']??$d['email'],$d['password']));}if($action==='me'){return $legacyUser? $this->ok($service->userData($legacyUser)):$this->fail('Authentication required',401);}if($action==='logout'){if(!$legacyUser)return $this->fail('Authentication required',401);$legacyUser->currentAccessToken()?->delete();return $this->ok();}return $this->fail('Unknown auth action',404);}
 public function complaints(Request $r){$action=$r->query('action','create');if($action==='create'){ $d=$r->validate(['customer_name'=>'nullable|string|max:190','customer_phone'=>'nullable|string|max:50','order_number'=>'nullable|string|max:60','message'=>'required|string|min:3','image_url'=>'nullable|string']);$d['user_id']=$r->user()?->id;$c=Complaint::create($d+['status'=>'open']);return $this->ok(['id'=>$c->id],201);}if(in_array($action,['admin-list','admin-update'],true) && (!$r->user() || $r->user()->role!=='admin')) return $this->fail('Admin access required',403);if($action==='admin-list')return $this->ok(Complaint::latest()->get());if($action==='admin-update'){$c=Complaint::findOrFail($r->input('id'));$c->update(['status'=>$r->input('status','open')]);return $this->ok();}return $this->fail('Unknown complaint action',404);}
 public function manage(Request $r){$resource=$r->query('resource');$action=$r->query('action','list');$d=$r->all();switch($resource){case 'products':if($action==='list')return $this->ok(Product::orderBy('sort_order')->latest()->get());if($action==='delete'){Product::whereKey($d['id'])->delete();return $this->ok();}if($action==='save'){ $data=$r->validate(['id'=>'nullable|string','legacy_id'=>'nullable|string','name'=>'required|string','slug'=>'required|string','description'=>'nullable|string','image_url'=>'nullable|string','gallery_urls'=>'nullable|array','old_price'=>'nullable|numeric','price'=>'numeric','stock_quantity'=>'integer','sold_quantity'=>'integer','discount_percent'=>'nullable|numeric','is_featured'=>'boolean','is_flash_sale'=>'boolean','is_hot_deal'=>'boolean','is_active'=>'boolean','sort_order'=>'integer','category_id'=>'nullable|string']);$id=$data['id']??null;if($id){$p=Product::findOrFail($id);$p->update($data);}else{$p=Product::create($data);}return $this->ok(['id'=>$p->id]);}break;case 'categories':if($action==='list')return $this->ok(Category::orderBy('sort_order')->latest()->get());if($action==='delete'){Category::whereKey($d['id'])->delete();return $this->ok();}if($action==='save'){ $data=$r->validate(['id'=>'nullable|string','name'=>'required|string','slug'=>'required|string','image_url'=>'nullable|string','is_active'=>'boolean','sort_order'=>'integer']);$c=!empty($data['id'])?Category::findOrFail($data['id']):new Category;$c->fill($data);$c->save();return $this->ok(['id'=>$c->id]);}break;case 'variants':if($action==='list')return $this->ok(ProductVariant::where('product_id',$r->input('product_id'))->orderBy('sort_order')->get());if($action==='delete'){ProductVariant::whereKey($d['id'])->delete();return $this->ok();}if($action==='save'){$data=$r->validate(['id'=>'nullable|string','product_id'=>'required|string','label'=>'required|string','weight_grams'=>'nullable|integer','price'=>'numeric','old_price'=>'nullable|numeric','stock_quantity'=>'integer','is_active'=>'boolean','sort_order'=>'integer']);$v=!empty($data['id'])?ProductVariant::findOrFail($data['id']):new ProductVariant;$v->fill($data);$v->save();return $this->ok(['id'=>$v->id]);}break;case 'coupons':if($action==='list')return $this->ok(Coupon::latest()->get());if($action==='delete'){Coupon::whereKey($d['id'])->delete();return $this->ok();}if($action==='save'){ $data=$r->validate(['id'=>'nullable|string','code'=>'required|string','discount_type'=>'required|in:percent,fixed','discount_value'=>'numeric','min_order'=>'numeric','max_discount'=>'nullable|numeric','usage_limit'=>'nullable|integer','used_count'=>'integer','is_active'=>'boolean','starts_at'=>'nullable|date','expires_at'=>'nullable|date']);$c=!empty($data['id'])?Coupon::findOrFail($data['id']):new Coupon;$c->fill($data);$c->code=strtoupper($c->code);$c->save();return $this->ok(['id'=>$c->id]);}break;case 'settings':if($action==='list')return $this->ok(SiteSetting::orderBy('setting_key')->get());if($action==='save'){$s=SiteSetting::updateOrCreate(['setting_key'=>$d['setting_key']],['setting_value'=>$d['setting_value']??null]);return $this->ok($s);}break;}return $this->fail('Unknown management action',404);}
 public function admin(Request $r){$action=$r->query('action');if($action==='dashboard'){ $counts=[];foreach(['products','categories','orders','complaints','coupons','users'] as $t)$counts[$t]=DB::table($t)->count();return $this->ok($counts);}if($action==='users')return $this->ok(DB::table('users')->leftJoin('profiles','profiles.id','=','users.id')->select('users.id','users.email','users.role','profiles.full_name','profiles.phone','users.created_at')->orderByDesc('users.created_at')->get());if($action==='products')return $this->ok(Product::orderBy('sort_order')->latest()->get());if($action==='categories')return $this->ok(Category::orderBy('sort_order')->latest()->get());return $this->fail('Unknown admin action',404);}
}
